from lib import *
S = SS('j254')
steps = [
    step("用 jcmd <pid> Compiler.queue 观察 JIT 编译队列:生成 3000 个小方法(每个 43 字节左右),各被调用数千次,JDK 21,本机默认 CICompilerCount = 4(10 个逻辑 CPU)。默认配置下取样 8 次:C1 队列一次都不是非空,C2 队列非空 3 次,长度最大 9,同时在编译的最多 3 个(C2 CompilerThread0..2 各编译一个方法,队列里排着 Flood::m53、m58……)。-XX:CICompilerCount=2(1 个 C1 + 1 个 C2)下取样 9 次:C2 队列非空 5 次,最大 7,同时在编译的只有 1 个。快照里每一行是 编译号、层级(4 = C2)、方法名(字节数)。", t=tl(S(1)), done=lidx(S(1), '本机默认 CICompilerCount = 4', '[默认编译线程]'), mark=lidx(S(1), 'CICompilerCount=2(1 个 C1', 'C2 CompilerThread0', 'C2 compile queue'), b=bars([['默认:C2 队列最大', 9, '9'], ['CICompilerCount=2:C2 队列最大', 7, '7'], ['默认:同时编译最多', 3, '3'], ['CICompilerCount=2:同时编译最多', 1, '1']], 9, done=[0, 1, 2, 3]), kv=KV([['C1 队列', '取样时一直是空的(C1 编译很快)'], ['C2 队列', '默认最长 9,CICompilerCount=2 最长 7'], ['同时在编译', '默认 3 个,CICompilerCount=2 时 1 个']], ['C2 队列'])),
    step("编译线程数对完成时间的影响(同一个负载:8 轮,每轮 3000 个方法 × 3000 次,每种设置跑 3 次取中位数):CICompilerCount=2:总用时 1861 ms;=3:1769 ms;默认(4):1730 ms;=8:1666 ms。第 0 轮(都在预热)从 406 ms 到 389 ms,第 7 轮(稳态)约 162–167 ms 几乎不变。线程从 2 个加到 8 个,总用时少约 10%,差别只发生在预热阶段。", t=tl(S(2)), done=lidx(S(2), 'CICompilerCount=2:总用时中位数', 'CICompilerCount=3'), mark=lidx(S(2), '默认(4)', 'CICompilerCount=8'), b=bars([['CICompilerCount=2', 1861, '1861 ms'], ['=3', 1769, '1769 ms'], ['默认(4)', 1730, '1730 ms'], ['=8', 1666, '1666 ms']], 1861, done=[0, 1, 2, 3]), kv=KV([['总用时', '2 个线程 1861 ms → 8 个线程 1666 ms(约 -10%)'], ['稳态(第 7 轮)', '162–167 ms,几乎不变']], ['总用时'])),
    step("-Xbatch 让编译阻塞调用线程(不再后台编译):同一个负载只跑 3 轮,默认后台编译总用时 898 ms(第 0 轮 409 ms、第 2 轮 205 ms);-Xbatch 总用时 1739 ms(第 0 轮 693 ms、第 2 轮 165 ms);-Xint 完全不编译总用时 2234 ms(每轮都是约 741 ms)。-Xbatch 到第 2 轮稳态更快(165 vs 205 ms,因为方法已经都编译完了),但代价是预热慢了近 2 倍:调用线程在等编译。后台编译用“先慢一点”换“不阻塞”。", t=tl(S(3)), done=lidx(S(3), '默认(后台编译)'), mark=lidx(S(3), '-Xbatch', '-Xint(不编译)'), b=bars([['默认(后台编译)', 898, '898 ms'], ['-Xbatch', 1739, '1739 ms'], ['-Xint', 2234, '2234 ms']], 2234, done=[0, 1, 2]), kv=KV([['默认', '3 轮 898 ms:第 0 轮 409 / 第 2 轮 205'], ['-Xbatch', '3 轮 1739 ms:第 0 轮 693 / 第 2 轮 165'], ['-Xint', '3 轮 2234 ms:每轮约 741']], ['-Xbatch'])),
    step("我原本想量“队列积压让热点方法的编译变晚”:Probe 的 probe() 每批 2000 次调用,另一个线程同时跑 3000 方法的洪水。结果没有观察到变晚:只有 Probe 与带洪水(默认编译线程、CICompilerCount=2)各跑 3 次,probe() 连续 5 批都不超过 1.5 倍稳态的起点都在第 39–41 批(约 4 ms;只有 CICompilerCount=2 洪水的第一次是第 4 批),稳态每批 0.053–0.056 ms,最慢的一批 0.29–0.44 ms。这个队列(最长 9 个)不够长,不足以拖慢它;我没有验证队列的选取顺序,也没有构造出更长的积压。", t=tl(S(4)), done=lidx(S(4), '[只有 Probe]'), mark=lidx(S(4), '[Probe + 洪水(默认编译线程)]', '[Probe + 洪水,CICompilerCount=2]'), kv=KV([['只有 Probe', '第 39–40 批(约 4 ms)进入稳态'], ['Probe + 洪水', '第 40–41 批(约 4 ms),没有变晚'], ['结论', '本实验的队列(最长 9)没有拖慢热点方法']], ['结论'])),
]
A = mkartj('j254', 254, 'Java,JIT,编译队列,jcmd,CICompilerCount,Xbatch,真实验证,动画演示',
    '用 jcmd Compiler.queue 在 JDK 21 上观察 JIT 编译队列:3000 个小方法的洪水下 C2 队列最长 9、同时编译 3 个(C1 队列始终为空);CICompilerCount 从 2 到 8 总用时 1861 → 1666 ms;-Xbatch 预热慢近 2 倍(1739 vs 898 ms);没有观察到热点方法被队列拖慢。',
    '有哪些方法正在排队等待 JIT 编译?这篇用 jcmd 取样编译队列,量出队列长度、编译线程数与完成时间的关系、-Xbatch 的代价,并如实记录一个预期没有出现的现象。',
    [('9', '3000 个方法的洪水下,C2 编译队列取样到的最大长度(C1 队列始终为空)'), ('1861 → 1666 ms', 'CICompilerCount 从 2 增加到 8 时同一负载的总用时'), ('1739 vs 898 ms', '-Xbatch 与默认后台编译的 3 轮总用时')],
    [('观察队列', None), ('编译线程数', None), ('-Xbatch', None), ('热点方法有没有变晚', None)],
    steps, [ENV_J + '。JDK 21.0.12;10 个逻辑 CPU,默认 CICompilerCount = 4;负载是生成的 3000 个小方法(Flood)与一个 40 次迭代循环的 probe 方法;取样间隔约 0.15 s,会错过更短的队列峰值', '没有验证:编译任务的选取顺序(热度 / 先后)、更大的方法与 JDK 25 / Graal 编译器下的队列、-XX:+PrintCompilation 日志的对照、代码缓存(CodeCache)满时的行为、JVMCI 编译线程'], 'JIT 编译队列')
